-- 003_seed_party_minimal.sql
-- Dev-only seed for crims.mdm.party + satellites (Option A 2026-09-23).
-- alpha.mdm.party is DROP'd; crims.mdm.party is the master extended with
-- alpha-only golden-record fields (see 002_crims_party_alter.sql).
-- Generated by gen_seed_party_minimal.py from information_schema so column
-- ordering stays in lockstep with the live schema.
-- Idempotent by id (uuid prefix aaaa9999-).

SET search_path = migration, crims, public;

BEGIN;

-- wipe prior seed
DELETE FROM crims.mdm.party_address WHERE party_id::text LIKE 'aaaa9999%';
DELETE FROM crims.mdm.party         WHERE id::text LIKE 'aaaa9999%';
DELETE FROM crims.mdm.xref          WHERE entity_type='party' AND entity_id::text LIKE 'aaaa9999%';

INSERT INTO crims.mdm.source_system
  (id, source_cd, name, system_type, vendor, connection_info, priority, is_active, custom_attributes, created_at, updated_at, tenant_id)
VALUES
  ('aaaa9999-9999-0000-0000-000000000099'::uuid,'SEED','seed_party_minimal.dev','SEED','uisce','{}'::jsonb,999,TRUE,'{"src":"seed_party_minimal"}'::jsonb,now(),now(),'99e99e99-99e9-49e9-89e9-99e99e99e999'::uuid),
  ('aaaa9999-9999-0000-0000-00000000009a'::uuid,'SEED','seed_party_minimal.gold','SEED','uisce','{}'::jsonb,999,TRUE,'{"src":"seed_party_minimal"}'::jsonb,now(),now(),'00000000-0000-0000-0000-000000000001'::uuid)
ON CONFLICT (id) DO NOTHING;

-- ensure party_address exists (party satellite; the main copy handles full DDL later)
CREATE TABLE IF NOT EXISTS crims.mdm.party_address (
  id uuid PRIMARY KEY, party_id uuid NOT NULL, address_type varchar(30) NOT NULL,
  address_line_1 varchar(255), address_line_2 varchar(255), address_line_3 varchar(255),
  city varchar(100), state_province varchar(100), postal_code varchar(20), country_cd varchar(2),
  is_primary boolean NOT NULL DEFAULT false, is_verified boolean NOT NULL DEFAULT false,
  verified_at timestamptz, verified_method varchar(30),
  effective_from date NOT NULL DEFAULT CURRENT_DATE, effective_to date,
  is_current boolean NOT NULL DEFAULT true,
  custom_attributes jsonb NOT NULL DEFAULT '{}'::jsonb,
  tenant_id uuid NOT NULL);

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='party_address_party_fkey') THEN
    ALTER TABLE crims.mdm.party_address
      ADD CONSTRAINT party_address_party_fkey FOREIGN KEY (party_id) REFERENCES crims.mdm.party(id) ON DELETE CASCADE;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_party_address_party ON crims.mdm.party_address (party_id);
CREATE INDEX IF NOT EXISTS idx_party_address_tenant ON crims.mdm.party_address (tenant_id);

