-- xref rows linking each party to its id (entity_type='party')
INSERT INTO crims.mdm.xref
  (id, entity_type, entity_id, source_system_id, external_id, external_type,
   is_primary, valid_from, valid_to, custom_attributes, created_at, updated_at, tenant_id)
SELECT
  ('aaaa9999-1111-0000-0000-00000000' || lpad(row_number() OVER ()::text, 4, '0'))::uuid,
  'party', p.id,
  (SELECT id FROM crims.mdm.source_system WHERE source_cd='SEED' AND tenant_id=p.tenant_id LIMIT 1),
  p.party_cd, 'INTERNAL', TRUE,
  p.valid_from::timestamptz, p.valid_to, '{"src":"seed_party_minimal"}'::jsonb,
  now(), now(), p.tenant_id
FROM crims.mdm.party p WHERE p.id::text LIKE 'aaaa9999%';

-- minimal party_address (one per party)
INSERT INTO crims.mdm.party_address
  (id, tenant_id, party_id, address_type,
   address_line_1, city, country_cd, postal_code,
   is_primary, is_verified, is_current, effective_from, custom_attributes)
SELECT
  ('aaaa9999-2222-0000-0000-00000000' || lpad(row_number() OVER ()::text, 4, '0'))::uuid,
  p.tenant_id, p.id, 'BUSINESS',
  '1 Seed Street', 'Seedville', p.domicile, '00000',
  TRUE, FALSE, TRUE, CURRENT_DATE, '{"src":"seed_party_minimal"}'::jsonb
FROM crims.mdm.party p WHERE p.id::text LIKE 'aaaa9999%';

-- row #7 golden_record_id = self (client_group anchor)
UPDATE crims.mdm.party SET golden_record_id=id WHERE id='aaaa9999-0000-0000-0000-000000000007'::uuid;

-- mark migration.progress(party) done
DO $$
DECLARE pid bigint;
BEGIN
  SELECT id INTO pid FROM migration.plan WHERE source_schema='mdm' AND source_table='party';
  IF pid IS NOT NULL THEN
    INSERT INTO migration.progress (plan_id, status, rows_copied, started_at, finished_at, detail)
      VALUES (pid, 'done', 8, now(), now(), 'seed_party_minimal: 8 parties + 8 xref + 8 addresses')
    ON CONFLICT (plan_id) DO UPDATE SET status='done', rows_copied=8, finished_at=now(), detail=EXCLUDED.detail;
  END IF;
END $$;

COMMIT;

